async function terrain(signal){const z=13,N=48,cache=new Map();async function sample(lon,lat){const n=2**z,px=(lon+180)/360*n*256,py=(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n*256,tx=Math.floor(px/256),ty=Math.floor(py/256),key=tx+'/'+ty;if(!cache.has(key))cache.set(key,(async()=>{const r=await fetch(`https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${key}.png`,{signal});if(!r.ok)throw Error('DEM HTTP '+r.status);const img=await createImageBitmap(await r.blob()),c=document.createElement('canvas');c.width=c.height=256;const ct=c.getContext('2d');ct.drawImage(img,0,0);img.close();return ct.getImageData(0,0,256,256).data})());const d=await cache.get(key),i=(Math.floor(py%256)*256+Math.floor(px%256))*4;if(d[i+3]!==255)throw Error('DEM содержит отсутствующие значения.');return d[i]*256+d[i+1]+d[i+2]/256-32768}const vals=[];for(let j=0;j<=N;j++){signal.throwIfAborted();for(let i=0;i<=N;i++)vals.push(await sample(bounds[1]+(bounds[3]-bounds[1])*i/N,bounds[0]+(bounds[2]-bounds[0])*j/N))}return {N,vals,min:Math.min(...vals)}}
