$('detail').onchange=render3d;['layerPaths','layerTrees','layerObjects','layerSurfaces','floorHeight','fallbackHeight','treeHeight','treeCrown','pathWidth','roadWidth','curbHeight','terrainMode','terrainBlend'].forEach(id=>$(id).onchange=()=>{if($(id).type==='number'&&!$(id).checkValidity()){$(id).reportValidity();return;}render3d();if(selectedId)showEditor();});$('obj').onclick=()=>{if(!scene||!grid)return alert('Откройте 3D-модель с загруженным рельефом');save(new Blob([new OBJExporter().parse(scene)],{type:'text/plain'}),'atlas-meters.obj')};
async function loadData(){buildRequest++;controller?.abort();controller=new AbortController();const signal=controller.signal,job=++generation;$('load').disabled=true;try{bounds=selection();clearOverrides();resetCamera=true;features=[];grid=null;downloadedAt=null;disposeScene();surfaceCache=null;activeSurface=null;baselineCache=null;plan();$('status').textContent='Загружаем объекты OpenStreetMap…';const result=await loadOSM([...bounds],{signal,onProgress:message=>{if(job===generation)$('status').textContent=message}});const data=result.data;if(job!==generation)return;features=osmtogeojson(data,{flatProperties:true}).features.filter(f=>!f.properties.tainted);downloadedAt=result.downloadedAt;try{await saveProject({features,bounds:[...bounds],side,downloadedAt,source:result.endpoint});}catch(e){console.warn('Не удалось сохранить участок для страницы экспорта',e);}if(job!==generation)return;plan();$('status').textContent='Объекты загружены. Получаем высоты рельефа…';try{const loaded=await terrain(signal);if(job!==generation)return;grid=loaded;saveProject({features,bounds:[...bounds],side,downloadedAt,source:result.endpoint,grid}).catch(()=>{});}catch(e){if(signal.aborted)throw e;$('status').textContent='План доступен. Рельеф недоступен: '+e.message;render3d();return}const bs=features.filter(building);$('status').textContent=`${result.cached?'Из кэша · ':''}Источник: ${new URL(result.endpoint).hostname}.${result.endpoint.endsWith('map.json')?' Резервная выгрузка: протяжённые объекты могут быть неполными.':''} Загружено зданий и частей: ${bs.length}; с тегом height: ${bs.filter(f=>height(f)!==null).length}. DEM z13; сетка 48×48, не геодезическая съёмка. Здания обрезаются границей участка; оценки высот отмечены в 3D.`;render3d()}catch(e){if(job!==generation)return;$('status').textContent='Не удалось загрузить данные: '+e.message}finally{if(job===generation){$('load').disabled=false;if($('reserve'))$('reserve').disabled=false}}};

$('geojson').onclick=()=>{if(!downloadedAt)return alert('Сначала загрузите данные');save(new Blob([JSON.stringify({type:'FeatureCollection',source:'OpenStreetMap / Overpass, ODbL',downloaded_at:downloadedAt,features},null,2)],{type:'application/geo+json'}),'atlas-source.geojson')};

