function showEditor(){const f=currentBuilding();if(!f)return;const c=overrides.get(selectedId)||{};$('buildingEditor').hidden=false;$('buildingTitle').textContent=f.properties.name||selectedId;$('buildingInfo').textContent=`OSM: ${selectedId}. Высота источника: ${height(f)??'не указана'} м. Нижняя отметка OSM: ${minimumHeight(f)??'некорректна'} м. Исходные теги: height=${f.properties.height??'отсутствует'}; min_height=${f.properties.min_height??'отсутствует'}; building:levels=${f.properties['building:levels']??'отсутствует'} (используется только в оценочном режиме). ${c.height?'Используется высота пользователя: '+c.height+' м.':''}`;const resolved=resolvedBuilding(f);$('buildingInfo').textContent+=' Текущая модель: '+(resolved.height??'нет объёма')+' м. '+resolved.source+'. '+resolved.warnings.join(' ')+(c.heightSource?' Источник пользовательской оценки: '+c.heightSource:'');if(activeSurface&&buildingGrades.has(selectedId))$('buildingInfo').textContent+=' Расчётная отметка площадки: '+buildingGrades.get(selectedId).toFixed(2)+' м над минимумом DEM участка.';$('buildingMode').value=c.mode||'footprint';$('userHeight').value=c.height??'';$('facadeEdge').value=(c.edge||0)+1;$('facadePhoto').value='';$('photoSource').value=c.source||'';$('photoCredit').value=c.credit||'';$('photoConfirmed').checked=false;const reference=photoReferences[selectedId];$('knownPhoto').hidden=!reference;if(reference){$('knownPhoto').href=reference.url;$('knownPhoto').textContent=reference.label;}const link=osmLink(selectedId);$('osmBuilding').hidden=!link;if(link)$('osmBuilding').href=link;$('searchBuilding').href=photoSearch(f);$('commonsSearch').href='https://commons.wikimedia.org/w/index.php?title=Special:MediaSearch&type=image&search='+encodeURIComponent(f.properties.name||[f.properties['addr:street'],f.properties['addr:housenumber']].filter(Boolean).join(' ')||selectedId);const commons=commonsLink(f.properties.wikimedia_commons);$('commonsBuilding').hidden=!commons;if(commons)$('commonsBuilding').href=commons;$('photoStatus').textContent=c.texture?'Фото на стороне (не 3D реконструкция). Источник: '+c.source:'Фотография не применена.';}
$('applyBuilding').onclick=()=>{if(!selectedId)return;const raw=$('userHeight').value.trim(),h=raw===''?undefined:Number(raw),edge=Number($('facadeEdge').value)-1;if(h!==undefined&&(!Number.isFinite(h)||h<=0||h>=1000)){alert('Высота должна быть больше 0 и меньше 1000 м.');return;}if(!Number.isInteger(edge)||edge<0){alert('Номер стороны должен быть целым числом от 1.');return;}const c=overrides.get(selectedId)||{};overrides.set(selectedId,{...c,height:h,heightSource:'Ввод пользователя',mode:$('buildingMode').value,edge});render3d();showEditor();};
$('resetBuilding').onclick=()=>{const c=overrides.get(selectedId);c?.texture?.dispose();c?.bitmap?.close?.();overrides.delete(selectedId);render3d();showEditor();};
$('removePhoto').onclick=()=>{const c=overrides.get(selectedId);if(c){c.texture?.dispose();c.bitmap?.close?.();delete c.texture;delete c.bitmap;delete c.source;}render3d();showEditor();};
$('facadePhoto').onchange=async e=>{const file=e.target.files[0],id=selectedId,job=generation;if(!file||!id)return;let source;try{source=new URL($('photoSource').value);if(!['https:','http:'].includes(source.protocol))throw Error();}catch{$('photoStatus').textContent='Укажите ссылку http/https на источник фотографии.';return;}if(!$('photoConfirmed').checked){$('photoStatus').textContent='Подтвердите соответствие фото зданию и стороне.';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){$('photoStatus').textContent='Допустимы JPG/PNG/WebP до 10 МБ.';return;}const f=currentBuilding(),c=overrides.get(id)||{},h=resolvedBuilding(f).height;if(!h){$('photoStatus').textContent='Для фасада нужна высота OSM или явно введённая высота пользователя.';return;}try{const bitmap=await createImageBitmap(file,{imageOrientation:'flipY',resizeWidth:2048});if(job!==generation||id!==selectedId){bitmap.close();return;}c.texture?.dispose();c.bitmap?.close?.();const texture=new THREE.Texture(bitmap);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;overrides.set(id,{...c,mode:c.mode||'footprint',texture,bitmap,source:source.href,credit:$('photoCredit').value.trim(),edge:Math.max(0,Number($('facadeEdge').value)-1)||0});render3d();showEditor();}catch{$('photoStatus').textContent='Не удалось прочитать изображение.';}};

$('exportSettings').onclick=()=>save(new Blob([JSON.stringify({type:'AtlasBuildingSettings',bounds,source:'OpenStreetMap',modelParameters:{terrainMode:$('terrainMode').value,terrainBlend:+$('terrainBlend').value,detail:$('detail').value,floorHeight:+$('floorHeight').value,fallbackHeight:+$('fallbackHeight').value,treeHeight:+$('treeHeight').value,treeCrown:+$('treeCrown').value,pathWidth:+$('pathWidth').value,roadWidth:+$('roadWidth').value,curbHeight:+$('curbHeight').value},overrides:[...overrides].map(([id,c])=>({id,mode:c.mode,height:c.height,heightSource:c.heightSource||(c.height?'user':resolvedBuilding(features.find(f=>featureId(f)===id)).source),photoSource:c.source,photoCredit:c.credit,side:(c.edge||0)+1,photoScale:c.photoScale,photoIncluded:false}))},null,2)],{type:'application/json'}),'atlas-building-settings.json');

$('applyPhotoHeight').onclick=()=>{if(!selectedId)return;try{const source=new URL($('photoSource').value);if(!['http:','https:'].includes(source.protocol)||!$('photoConfirmed').checked)throw Error('Укажите источник фото и подтвердите соответствие зданию.');if(!$('photoScaleConfirmed').checked)throw Error('Подтвердите масштаб и плоскость измерения.');const height=photoHeight($('photoReferenceMeters').value,$('photoReferencePixels').value,$('photoBuildingPixels').value),c=overrides.get(selectedId)||{};overrides.set(selectedId,{...c,height,heightSource:'Оценка по масштабу фотографии: '+source.href,photoScale:{referenceMeters:+$('photoReferenceMeters').value,referencePixels:+$('photoReferencePixels').value,buildingPixels:+$('photoBuildingPixels').value}});render3d();showEditor();}catch(e){$('photoStatus').textContent=e.message;}};

// Start with a monochrome base; preserve explicit layer choices within this browser.
const storedPlan=readPlanPreferences();$('kind').value=storedPlan.mode;for(const [key,id] of Object.entries(planIds))$(id).checked=storedPlan.layers[key];mark();

async function restoreSavedProject(){const job=generation;try{const saved=await readProject();if(job!==generation||!saved?.bounds||!Array.isArray(saved.features))return;bounds=saved.bounds;side=saved.side;features=saved.features;downloadedAt=saved.downloadedAt;grid=saved.grid||null;$('lat').value=((bounds[0]+bounds[2])/2).toFixed(6);$('lon').value=((bounds[1]+bounds[3])/2).toFixed(6);$('area').value=(side*side/1e6).toFixed(2);if(box)map.removeLayer(box);box=L.rectangle([[bounds[0],bounds[1]],[bounds[2],bounds[3]]],{color:'#305d42',weight:2}).addTo(map);map.fitBounds(box.getBounds(),{padding:[30,30]});$('status').textContent='Восстановлен последний загруженный участок. Данные: '+new Date(downloadedAt).toLocaleDateString('ru-RU')+'. Для обновления нажмите «Получить геоданные».';plan();if(!$('model').hidden)render3d();}catch{}}
restoreSavedProject();if(location.hash==='#plans')document.querySelector('[data-tab="plans"]').click();


